create function pg_temp.v() returns bigint language sql security definer set search_path='' as $$select coalesce((select version from public.team_plans where team_id='60000000-0000-0000-0000-000000000010'),0)$$;
create function pg_temp.r() returns uuid language sql security definer set search_path='' as $$select id from public.team_leave_requests where team_id='60000000-0000-0000-0000-000000000010' and user_id='60000000-0000-0000-0000-000000000002' and description='private note' order by created_at limit 1$$;
set local role authenticated;set local request.jwt.claims='{"sub":"60000000-0000-0000-0000-000000000001"}';
