select throws_ok($q$select public.create_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),'2026-10-27','2026-10-25','private note')$q$,'22023',null,'reversed dates denied');
select throws_ok($q$select public.create_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),'infinity','infinity','private note')$q$,'22023',null,'infinite dates denied');
