select throws_ok($q$select public.act_on_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),pg_temp.r(),0,'approve','')$q$,'42501',null,'employee cannot approve self');
select throws_ok($q$select public.act_on_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),pg_temp.r(),0,'reject','no')$q$,'42501',null,'employee cannot reject self');
select throws_ok($q$select public.act_on_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),pg_temp.r(),0,'cancel','no')$q$,'42501',null,'employee cannot cancel approved leave');
select throws_ok('select * from public.team_leave_requests','42501',null,'no direct team_leave_requests read');
