select throws_ok('delete from public.team_leave_requests','42501',null,'history cannot be deleted by client');
select throws_ok('select * from public.team_leave_events','42501',null,'no direct team_leave_events read');
select throws_ok('update public.team_leave_events set status=''approved''','42501',null,'no direct team_leave_events update');
select throws_ok('delete from public.team_leave_events','42501',null,'history cannot be deleted by client');
