select throws_ok($q$select public.act_on_team_leave('60000000-0000-0000-0000-000000000010',pg_temp.v(),pg_temp.r(),0,'withdraw','')$q$,'42501',null,'other employee cannot withdraw');
set local role authenticated;set local request.jwt.claims='{"sub":"60000000-0000-0000-0000-000000000004"}';
