select throws_ok($q$select public.save_team_shift('60000000-0000-0000-0000-000000000010',pg_temp.v(),null,'60000000-0000-0000-0000-000000000002','2026-10-26 23:00','2026-10-27 01:00',0,'Night','')$q$,'P1001',null,'last inclusive day blocked');
