select is(public.read_team_leaves('60000000-0000-0000-0000-000000000010')->'requests'->0->>'decided_by','60000000-0000-0000-0000-000000000005','cancellation actor recorded');
select is(jsonb_array_length(public.read_team_plan('60000000-0000-0000-0000-000000000010',false)->'leaves'),0,'cancelled leave removed from calendar');
