select lives_ok(format('select public.act_on_team_leave(%L,pg_temp.v(),%L,0,''withdraw'','''')','60000000-0000-0000-0000-000000000010',:'second_id'),'own pending request can be withdrawn');
select is(public.read_team_leaves('60000000-0000-0000-0000-000000000010')->'requests'->0->>'status','cancelled','withdrawal shown cancelled');
